    """
    if not isinstance(chapter_mission, dict):
        return []
    names: List[str] = []
    seen: set = set()

    def add_name(value: Any) -> None:
        if not value:
            return
        if isinstance(value, dict):
            for item in value.values():
                add_name(item)
            return
        if isinstance(value, list):
